/* Customer-only, portable appointment/profile snapshot; no merchant data is exported. */
(function(root){
 const css=`*{box-sizing:border-box}body{margin:0;background:#f5f0e5;color:#173b31;font:16px/1.7 "Microsoft YaHei",sans-serif}main{max-width:860px;margin:auto;padding:28px 18px}header{display:flex;gap:16px;align-items:center;margin-bottom:24px}h1{margin:0;font-size:28px}h2{font-size:20px;margin-top:0}.avatar{background:#173b31;color:#fffdf8;border-radius:50%;width:56px;height:56px;display:grid;place-items:center;font-size:24px}.card{background:#fffdf8;border:1px solid #d9dece;border-radius:22px;padding:22px;margin:16px 0}.muted{font-size:14px;color:#667d6f}.notice{padding:12px 16px;background:#e8eddf;border-radius:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}small{display:block;color:#667d6f}button{border:1px solid #173b31;border-radius:14px;padding:10px 16px;background:#173b31;color:#fffdf8;cursor:pointer;font:inherit}button.secondary{background:#f5f0e5;color:#173b31}.actions{display:flex;gap:10px;flex-wrap:wrap}input,textarea{width:100%;font:inherit;border:1px solid #bcc9b7;background:#fffdf8;border-radius:12px;padding:12px;color:#173b31}label{display:block;margin:12px 0}textarea{min-height:80px}form button{margin-top:10px}.messages{display:flex;flex-direction:column;gap:12px;max-height:400px;overflow:auto;margin:16px 0}.bubble{max-width:90%;padding:12px 16px;border-radius:16px;background:#eef1e8;white-space:pre-wrap}.bubble.user{align-self:flex-end;background:#173b31;color:#fffdf8}#request-result{white-space:pre-wrap}@media(max-width:600px){.grid{grid-template-columns:1fr}h1{font-size:23px}}`;
 function validate(p){
  if(!p||p.version!==1||typeof p.name!=='string'||!p.name.trim()||p.name.length>40)throw Error('专属助手资料无效，请向店主重新获取');
  return p;
 }
 function personalAssistantRuntime(profile){
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const project={cut:'洗剪吹',color:'染发',perm:'烫发',care:'护理'},clock=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
  let current={...profile};
  try{const saved=JSON.parse(localStorage.getItem('salon-personal-'+profile.id)||'null');if(saved)for(const k of ['name','cycle','preferredWindow','goal'])if(saved[k]!==undefined)current[k]=saved[k];}catch{}
  const booking=profile.booking;
  document.body.innerHTML=`<main><header><span class="avatar">${esc(current.name.slice(0,1))}</span><div><h1>${esc(current.name)}的理发管家</h1><div class="muted">门店为你准备的专属服务档案</div></div></header><p class="notice">这是生成时的个人档案与预约快照，暂未联网同步。时间变更、提醒和新预约请与店主确认；本页不会自动发送通知。</p><section class="card"><h2>我的预约</h2>${booking?`<p><b>${esc(booking.day)} ${clock(booking.start)}–${clock(booking.start+booking.duration)}</b></p><p>${esc(project[booking.project]||'理发服务')} · 预计 ${booking.duration} 分钟</p><p class="muted">${booking.status==='confirmed'?'店主已保存的预约记录（以门店最新安排为准）':'待店主确认或保存，尚未预约成功'}</p>`:'<p class="muted">暂无预约记录，请与店主约定到店时间。</p>'}</section><section class="card" id="personal-profile-panel"><h2>我的资料</h2><div class="grid"><div><small>称呼</small>${esc(current.name)}</div><div><small>常做项目</small>${esc(project[current.project]||'待记录')}</div><div><small>上次实际到店</small>${esc(current.lastVisit||'待记录')}</div><div><small>偏好时间</small>${esc(current.preferredWindow||'待了解')}</div></div><p>${esc(current.goal||'暂无剪发偏好记录')}</p><details><summary>编辑我的偏好</summary><form id="personal-profile"><label>称呼<input name="name" required maxlength="40" value="${esc(current.name)}"></label><label>维护周期（天）<input name="cycle" type="number" min="7" max="180" value="${esc(current.cycle||'')}"></label><label>常用时间<input name="preferredWindow" maxlength="60" value="${esc(current.preferredWindow||'')}"></label><label>剪发习惯<textarea name="goal" maxlength="500">${esc(current.goal||'')}</textarea></label><button>保存到本设备</button></form></details><div id="personal-visits"></div><span id="personal-cycle" hidden></span></section><section class="card"><h2>和我的助手说说</h2><p class="muted">当前使用规则回答，未连接真实大模型。</p><div class="actions"><button type="button" data-question="查看我的预约">我的预约</button><button type="button" data-question="什么时候该理发">下次理发</button><button type="button" data-question="我想预约">准备预约需求</button></div><div id="personal-messages" class="messages"></div><form id="personal-chat"><label>消息<textarea id="personal-text" placeholder="例如：我的预约是几点？"></textarea></label><button type="submit">发送</button></form></section><section id="request-card" class="card" hidden><h2>发给店主的预约需求</h2><p class="muted">这里无法读取门店实时空位。生成文字后，复制到微信发给店主确认。</p><label>希望到店日期<input id="request-day" type="date"></label><label>希望到店时间<input id="request-time" type="time"></label><button id="make-request" type="button">生成预约需求文字</button><textarea id="request-result" aria-label="预约需求文字" readonly></textarea><button type="button" id="copy-request">复制需求文字</button><p id="request-status" role="status"></p></section></main>`;
  const $=s=>document.querySelector(s);
  function cycle(){if(!current.lastVisit||!Number(current.cycle))return $('#personal-cycle').textContent='还未记录到店日期或维护周期，可先和店主确定。';const date=new Date(current.lastVisit+'T12:00:00+08:00');date.setUTCDate(date.getUTCDate()+Number(current.cycle));$('#personal-cycle').textContent='建议在 '+new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)+' 前后关注发型（不是已预约时间）。';}
  cycle();
  const visits=profile.visits||[];$('#personal-visits').innerHTML='<h2>到店记录</h2><p>已记录 '+visits.length+' 次到店</p>'+(visits.length?visits.map((v,i)=>'<div class="notice"><b>'+esc(v.day)+(Number.isFinite(v.start)?' '+clock(v.start):'')+'</b><p>'+v.projects.map(p=>esc(project[p]||p)).join(' · ')+' · 第 '+(visits.length-i)+' 次</p></div>').join(''):'<p class="muted">暂无完整的实际到店记录，请店主补记。未完成预约不计入次数。</p>');
  const care=profile.care;
  if(care?.items?.length){
   const box=document.createElement('section');box.className='card';$('#personal-profile-panel').after(box);
   const dateNow=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
   const after30=d=>{const t=new Date(d+'T12:00:00+08:00');t.setUTCDate(t.getUTCDate()+30);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(t);};
   let preferences={};try{preferences=JSON.parse(localStorage.getItem('salon-care-'+profile.id)||'{}');}catch{}
   const renderCare=()=>{const now=dateNow(),show=care.recommendation&&now<=care.recommendation.expiresOn&&!preferences.disabled&&(!preferences.until||now>=preferences.until)&&(!preferences.lastShown||preferences.lastShown===now||now>=after30(preferences.lastShown));
    box.innerHTML='<h2>护理注意事项</h2>'+care.items.map(x=>'<h3>'+esc(x.title)+'</h3><p style="white-space:pre-wrap">'+esc(x.text||'店主暂未填写，后续会补充。')+'</p>').join('')+(show?'<h3>有需要时再考虑</h3><p>'+esc(care.recommendation.text)+'</p><p class="muted">可选建议，不是必须做的项目；最多每30天展示一次。</p><div class="actions"><button type="button" id="care-later">暂不需要</button><button type="button" id="care-off">关闭项目建议</button></div>':preferences.disabled?'<button type="button" id="care-on">重新开启项目建议</button>':'');
    if(show){preferences.lastShown=now;try{localStorage.setItem('salon-care-'+profile.id,JSON.stringify(preferences));}catch{}}
    const persist=()=>{try{localStorage.setItem('salon-care-'+profile.id,JSON.stringify(preferences));}catch{}renderCare();};
    if($('#care-later'))$('#care-later').onclick=()=>{preferences.until=after30(now);persist();};
    if($('#care-off'))$('#care-off').onclick=()=>{preferences.disabled=true;persist();};
    if($('#care-on'))$('#care-on').onclick=()=>{preferences.disabled=false;persist();};
   };renderCare();
  }
  function message(text,role){const el=document.createElement('div');el.className='bubble '+role;el.textContent=text;$('#personal-messages').append(el);el.scrollIntoView({block:'nearest'});}
  function answer(text){message(text,'user');if(/预约|几点|时间/.test(text)&&!/想|帮|下次/.test(text)){message(booking?`记录显示：${booking.day} ${clock(booking.start)}，${project[booking.project]||'理发服务'}。${booking.status==='confirmed'?'请以店主最新确认的安排为准。':'这笔记录尚未预约成功，请联系店主。'}`:'暂时没有预约记录，可以让我帮你整理预约需求。','assistant');}else if(/周期|该理发|下次|多久/.test(text)){message($('#personal-cycle').textContent,'assistant');}else if(/预约|剪发|理发/.test(text)){$('#request-card').hidden=false;message('请在下方填写希望到店的日期和时间，我会生成文字供你发给店主。需店主确认后才算预约成功。','assistant');}else{message('我可以帮你查看预约、查看维护周期，或整理预约需求。发型方案、价格和护理请直接向店主确认。','assistant');}}
  $('#personal-chat').onsubmit=e=>{e.preventDefault();const text=$('#personal-text').value.trim();if(text){$('#personal-text').value='';answer(text);}};
  $('#personal-text').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();$('#personal-chat').requestSubmit();}};
  document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>answer(b.dataset.question));
  $('#personal-profile').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{localStorage.setItem('salon-personal-'+profile.id,JSON.stringify(data));current={...current,...data};document.querySelector('h1').textContent=current.name+'的理发管家';document.querySelector('.avatar').textContent=current.name.slice(0,1);cycle();message('偏好已保存到本设备，尚未同步给店主。','assistant');}catch{message('本设备无法保存资料，请检查浏览器存储设置。','assistant');}};
  $('#make-request').onclick=()=>{const day=$('#request-day').value,time=$('#request-time').value;if(!day||!time){$('#request-status').textContent='请先填写希望到店的日期和时间。';return;}$('#request-result').value=`您好，我是${current.name}，想在${day} ${time}到店做${project[current.project]||'理发服务'}。${current.goal?'偏好：'+current.goal+'。':''}请帮我确认能否安排。`;$('#request-status').textContent='需求文字已生成，还未创建预约。';};
  $('#copy-request').onclick=async()=>{const text=$('#request-result').value;if(!text)return;try{await navigator.clipboard.writeText(text);$('#request-status').textContent='已复制，请通过微信发给店主。';}catch{$('#request-result').focus();$('#request-result').select();$('#request-status').textContent='请长按或按 Ctrl+C 复制选中的文字。';}};
 }
 function makeHTML(p){validate(p);const safe=JSON.stringify(p).replace(/</g,'\\u003c');return '<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>我的专属理发助手</title><style>'+css+'</style></head><body><script>('+personalAssistantRuntime.toString()+')('+safe+');<'+ '/script></body></html>';}
 function makeURL(p,href){validate(p);const url=new URL('customer-assistant.html',href);url.hash='invite='+encodeURIComponent(JSON.stringify(p));return url.href;}
 root.SalonInvite={makeHTML,makeURL,validate};
 if(typeof document!=='undefined'&&document.body?.dataset.personalAssistant==='true'){
  try{const raw=location.hash.replace(/^#invite=/,'');if(raw.length>50000)throw Error('资料过长');const p=validate(JSON.parse(decodeURIComponent(raw)));const style=document.createElement('style');style.textContent=css;document.head.append(style);personalAssistantRuntime(p);}catch{document.body.textContent='未找到有效的客户专属资料，请向店主重新获取链接。';}
 }
})(globalThis);
